import java.lang.management.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<String> heap = new ArrayList<>(), nonHeap = new ArrayList<>();
        for (MemoryPoolMXBean p : ManagementFactory.getMemoryPoolMXBeans())
            (p.getType() == MemoryType.HEAP ? heap : nonHeap).add(p.getName());
        Collections.sort(heap);
        Collections.sort(nonHeap);
        System.out.println("=== runtime data areas (as seen by MemoryPoolMXBean) ===");
        System.out.println("heap pools     : " + heap);
        System.out.println("non-heap pools : " + nonHeap);

        MemoryUsage h = ManagementFactory.getMemoryMXBean().getHeapMemoryUsage();
        System.out.println("=== heap usage sanity (absolute numbers are machine dependent) ===");
        System.out.println("committed > 0            : " + (h.getCommitted() > 0));
        System.out.println("max > 0                  : " + (h.getMax() > 0));
        System.out.println("used <= committed        : " + (h.getUsed() <= h.getCommitted()));

        List<String> gcs = new ArrayList<>();
        for (GarbageCollectorMXBean g : ManagementFactory.getGarbageCollectorMXBeans())
            gcs.add(g.getName());
        Collections.sort(gcs);
        System.out.println("=== collectors ===");
        System.out.println("collectors : " + gcs);
        System.out.println("GC names contain 'G1' : " + gcs.toString().contains("G1"));
    }
}
